import os
from moler.util.moler_test import MolerTest  # type: ignore
from taf.ul.sc.perf.tc import tc
from taf.ul.sc.perf.post.interfaces.post_process import PostProcess
from taf.ul.sc.perf.post.interfaces.database_data import DatabaseDataInterface
from taf.ul.sc.perf.post.interfaces.logs_processing import LogsProcessingInterface
from taf.ul.sc.perf.post.interfaces.test_results_validation import TestResultsValidationInterface
from taf.ul.sc.perf.post.interfaces.coop import CoopInterface
from taf.ul.sc.util.helpers import generate_unix_remote_device  # type: ignore
from taf.ul.sc.perf.util.logger import log_debug_function_info
from taf.ul.sc.perf.messenger import get_receivers_for_test_results


__all__ = ['PostRunner']


class PostUtil(object):
    def run_creating_logs_package_in_the_background(self):
        source_dir = os.path.join(tc.output_dir, "")
        run_script_cmd = 'post_runner --sourcedir {} --mode create_logs_package 2>&1 ' \
                         '| tee -a {}create_package_console.log'.format(source_dir, source_dir)
        self._fire_script_in_the_background(run_script_cmd)

    def run_post_process_on_local_server_in_the_background(self):
        source_dir = os.path.join(tc.output_dir, "")
        run_script_cmd = 'post_runner --sourcedir {} 2>&1 | tee -a {}post_console.log'.format(source_dir, source_dir)
        self._fire_script_in_the_background(run_script_cmd)

    @staticmethod
    def _fire_script_in_the_background(run_script_cmd):
        run_cmd = 'bash -c "{}"'.format(run_script_cmd)
        screen_cmd = 'screen -d -m -S "POST-{}-{}" -t "POST-{}" {}'. \
            format(tc.test_line_name, tc.execution_date, tc.test_case_name, run_cmd)
        access_cmd = 'screen -r -S "POST-{}-{}"'.format(tc.test_line_name, tc.execution_date)

        MolerTest.info(msg=screen_cmd)
        msg = "To access it use: {}".format(access_cmd)

        MolerTest.info(msg=msg)
        os.system(screen_cmd)

    @staticmethod
    def _generate_logstore_server_device():
        logstore_server = tc.run_params['environment']['logstore_server']
        generate_unix_remote_device(device_name="LOGSTORE_SERVER",
                                    host=logstore_server['host'],
                                    login=logstore_server['login'],
                                    password=logstore_server['password'])


class PostInterface(
        LogsProcessingInterface,
        DatabaseDataInterface,
        TestResultsValidationInterface,
        CoopInterface):

    @log_debug_function_info()
    def process_results(self):
        if tc.is_feature_enabled("process_logs"):
            self.processing_logs()

    def make_post_directory_and_move_logs(self):
        params = {}
        if tc.run_params['post_process']['type'] == 'ute_cloud_manager':
            params = {'omit_robot_files': True, 'omit_previous_tests': True}

        self.pp.make_post_directory()
        self.pp.move_logs_to_post_directory(**params)

    @log_debug_function_info()
    def create_package_and_send_to_logstore(self):

        self.pp.create_logs_package()
        if tc.is_feature_enabled("remove_post_dir"):
            self.pp.remove_post_directory()

        if tc.is_feature_enabled("send_package_to_logstore"):
            self.pp.send_package_to_logstore()
        if tc.is_feature_enabled("send_mail_with_test_results") and tc.tester_username:
            self.pp.send_mail_with_test_results(test_execution_id=tc.database_id,
                                                test_status=tc.current_test_case_status,
                                                validation_link=tc.validation_url_link)


class PostRunnerInterface(object):

    def post_process_in_the_background(self):          # Run by post_runner script when BG mode
        self.make_post_directory_and_move_logs()
        self.process_and_validate_results()
        self.create_package_and_send_to_logstore()

    def create_logs_package_in_the_background(self):   # Run by post_runner script when FG mode
        self.make_post_directory_and_move_logs()
        self.create_package_and_send_to_logstore()


class PostRunner(
        PostUtil,
        PostInterface,
        PostRunnerInterface):

    def __init__(self):
        self._generate_logstore_server_device()
        self.pp = PostProcess(source_dir=tc.output_dir,
                              test_case_name=tc.test_case_name,
                              build=tc.bts_build,
                              release=tc.bts_release,
                              test_line_name=tc.test_line_name,
                              tester_username=get_receivers_for_test_results(),
                              permalink=tc.database_permalink,
                              teb_url=tc.run_params['environment']['teb_url'],
                              base_logstore_path=tc.run_params['environment']['base_logstore_path'],
                              base_logstore_url=tc.run_params['environment']['base_logstore_url'])

    def run_post_process_in_the_foreground(self):
        self.process_results()
        self.run_creating_logs_package_in_the_background()

    def run_post_process_for_cm(self):
        """
        Post process used when test is running via UTE Cloud Manager
        :return:
        """
        self.process_results()
        self.run_creating_logs_package_in_the_background()

    def run_post_process_in_the_background(self, run_type="local"):
        """

        :param run_type: possible values" local, remote, jenkins
        :return:
        """
        if "environment" not in tc.run_params:
            MolerTest.warning(msg="environment params not available. Can not run post processing")
            return
        if run_type == "local":
            self.run_post_process_on_local_server_in_the_background()
